// The rules the brief requires, over the spec's state
// { run, task0, task1, w0, w1, msgs }.

const tasks = (s) => [s.task0, s.task1];
const workers = (s) => [s.w0, s.w1];
const ENDED = ['completed', 'failed', 'cancelled'];
const reported = (t) => ENDED.includes(t);
const count = (s, m) => s.msgs.filter((x) => x === m).length;
const reportsFrom = (s, i) => s.msgs.filter((x) => x.startsWith(`Report:${i}:`)).length;

export const stateInvariants = [
  {
    name: 'completed-only-when-both-tasks-completed',
    pred: (s) => s.run !== 'completed' || (s.task0 === 'completed' && s.task1 === 'completed'),
  },
  {
    name: 'ends-only-when-both-reported',
    pred: (s) => !ENDED.includes(s.run) || tasks(s).every(reported),
  },
  {
    name: 'status-follows-reports',
    pred: (s) => {
      if (!['running', 'cancelling', ...ENDED].includes(s.run)) return true;
      const [a, b] = tasks(s);
      if (a === 'completed' && b === 'completed') return s.run === 'completed';
      if (!(reported(a) && reported(b))) return s.run === 'running' || s.run === 'cancelling';
      if (a === 'failed' || b === 'failed') return s.run === 'failed';
      return s.run === 'cancelled';
    },
  },
  {
    name: 'idle-run-has-idle-tasks-and-workers',
    pred: (s) => s.run !== 'idle' || (tasks(s).every((t) => t === 'idle') && workers(s).every((w) => w === 'idle') && s.msgs.length === 0),
  },
  {
    name: 'started-run-has-no-idle-task',
    pred: (s) => s.run === 'idle' || tasks(s).every((t) => t !== 'idle'),
  },
  {
    name: 'no-cancelled-task-without-cancel',
    pred: (s) => s.run !== 'running' || tasks(s).every((t) => t !== 'cancelled'),
  },
  {
    name: 'busy-worker-task-is-unreported',
    pred: (s) => [0, 1].every((i) => workers(s)[i] !== 'busy' || tasks(s)[i] === 'assigned'),
  },
  {
    name: 'at-most-one-report-per-task',
    pred: (s) => [0, 1].every((i) => reportsFrom(s, i) + (reported(tasks(s)[i]) ? 1 : 0) <= 1),
  },
  {
    name: 'at-most-one-assign-and-abort-per-worker',
    pred: (s) => [0, 1].every((i) => count(s, `Assign:${i}`) <= 1 && count(s, `Abort:${i}`) <= 1),
  },
];

export const transitionInvariants = [
  {
    name: 'cancel-aborts-only-assigned-tasks',
    pred: (pre, action, data, post) => {
      if (action !== 'CANCEL' || pre.run === post.run) return true;
      return [0, 1].every((i) => (count(post, `Abort:${i}`) > count(pre, `Abort:${i}`)) === (pre[`task${i}`] === 'assigned'));
    },
  },
  {
    name: 'abort-stops-only-work-in-progress',
    pred: (pre, action, data, post) => {
      if (action !== 'DELIVER_ABORT') return true;
      const k = `w${data.w}`;
      if (pre[k] !== 'busy') return post[k] === pre[k] && reportsFrom(post, data.w) === reportsFrom(pre, data.w);
      return post[k] === 'idle' && count(post, `Report:${data.w}:cancelled`) === count(pre, `Report:${data.w}:cancelled`) + 1;
    },
  },
  {
    name: 'ended-run-is-final',
    pred: (pre, action, data, post) => !ENDED.includes(pre.run) || (post.run === pre.run && post.task0 === pre.task0 && post.task1 === pre.task1),
  },
  {
    name: 'task-status-only-from-a-matching-report',
    pred: (pre, action, data, post) => [0, 1].every((i) => {
      const k = `task${i}`;
      if (pre[k] === post[k]) return true;
      if (action === 'START') return pre[k] === 'idle' && post[k] === 'assigned';
      return action === 'DELIVER_REPORT' && data.w === i && pre[k] === 'assigned' && post[k] === data.outcome;
    }),
  },
];

export default { stateInvariants, transitionInvariants };

