import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';
import type { Host, Message } from '../host.ts';
// @ts-ignore -- plain JS module from the polygraph tool
import { loadSpec } from '../tools/polygraph/scripts/load-spec.mjs';

const deliverWhere = async (h: Host, pred: (m: Message) => boolean) => {
  const m = (await h.inFlight()).find(pred);
  assert.ok(m, 'expected message in flight');
  await h.deliver(m.id);
};

test('fresh system is idle', async () => {
  const h = await createHost();
  assert.deepEqual(await h.run(), { status: 'idle', task0: 'idle', task1: 'idle' });
  assert.deepEqual(await h.worker('worker0'), { status: 'idle' });
  assert.equal(await h.worker('nobody'), null);
  assert.deepEqual(await h.inFlight(), []);
  assert.equal((await h.cancel()).ok, false);
  assert.equal((await h.workDone('worker0')).ok, false);
  assert.equal((await h.workDone('x')).ok, false);
});

test('happy path completes', async () => {
  const h = await createHost();
  assert.deepEqual(await h.start(), { ok: true });
  assert.equal((await h.start()).ok, false);
  const msgs = await h.inFlight();
  assert.equal(msgs.length, 2);
  assert.deepEqual(msgs.map((m) => [m.from, m.to, m.action, m.data]).sort(), [
    ['run', 'worker0', 'Assign', {}],
    ['run', 'worker1', 'Assign', {}],
  ]);
  await h.deliverAll();
  assert.deepEqual(await h.worker('worker1'), { status: 'busy' });
  assert.deepEqual(await h.workDone('worker0'), { ok: true });
  const [r] = await h.inFlight();
  assert.deepEqual([r.from, r.to, r.action, r.data], ['worker0', 'run', 'Report', { task: 0, outcome: 'completed' }]);
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'running', task0: 'completed', task1: 'assigned' });
  await h.workDone('worker1');
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'completed', task0: 'completed', task1: 'completed' });
});

test('failure', async () => {
  const h = await createHost();
  await h.start();
  await h.deliverAll();
  await h.workFailed('worker1');
  await h.deliverAll();
  assert.equal((await h.run()).status, 'running');
  await h.workDone('worker0');
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'failed', task0: 'completed', task1: 'failed' });
});

test('cancel aborts only assigned tasks', async () => {
  const h = await createHost();
  await h.start();
  await h.deliverAll();
  await h.workDone('worker0');
  await h.deliverAll();
  assert.deepEqual(await h.cancel(), { ok: true });
  assert.equal((await h.cancel()).ok, false);
  const msgs = await h.inFlight();
  assert.deepEqual(msgs.map((m) => [m.to, m.action]), [['worker1', 'Abort']]);
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'cancelled', task0: 'completed', task1: 'cancelled' });
  assert.deepEqual(await h.worker('worker1'), { status: 'idle' });
});

test('completion report racing an abort still completes', async () => {
  const h = await createHost();
  await h.start();
  await h.deliverAll();
  await h.workDone('worker0');
  await h.workDone('worker1');
  await h.cancel();
  assert.equal((await h.run()).status, 'cancelling');
  await deliverWhere(h, (m) => m.action === 'Abort');
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'completed', task0: 'completed', task1: 'completed' });
});

// Conformance: random walks through the implementation, mirrored step by step
// on the polygraph spec; their observable states must agree at every step.
test('implementation conforms to spec/run-workers.cjs', async () => {
  const spec = loadSpec(new URL('../spec/run-workers.cjs', import.meta.url).pathname.replace(/^\/(\w:)/, '$1'));
  let seed = 12345;
  const rand = (n: number) => {
    seed = (seed * 1103515245 + 12345) % 2 ** 31;
    return seed % n;
  };
  const project = async (h: Host) => {
    const r = await h.run();
    const msgs = (await h.inFlight()).map((m) => {
      if (m.action === 'Report') return `Report:${m.data.task}:${m.data.outcome}`;
      return `${m.action}:${m.to === 'worker0' ? 0 : 1}`;
    }).sort();
    return {
      run: r.status, task0: r.task0, task1: r.task1,
      w0: (await h.worker('worker0'))!.status, w1: (await h.worker('worker1'))!.status, msgs,
    };
  };
  for (let walk = 0; walk < 300; walk++) {
    const h = await createHost();
    spec.init();
    for (let step = 0; step < 14; step++) {
      const msgs = await h.inFlight();
      const choice = rand(5 + msgs.length);
      const w = rand(2);
      const wid = `worker${w}`;
      if (choice === 0) { await h.start(); spec.actions.START({}); }
      else if (choice === 1) { await h.cancel(); spec.actions.CANCEL({}); }
      else if (choice === 2) { await h.workDone(wid); spec.actions.WORK_DONE({ w }); }
      else if (choice === 3) { await h.workFailed(wid); spec.actions.WORK_FAILED({ w }); }
      else if (choice === 4) { await h.workDone('bogus'); }
      else {
        const m = msgs[choice - 5];
        await h.deliver(m.id);
        if (m.action === 'Report') spec.actions.DELIVER_REPORT({ w: m.data.task, outcome: m.data.outcome });
        else if (m.action === 'Assign') spec.actions.DELIVER_ASSIGN({ w: m.to === 'worker0' ? 0 : 1 });
        else spec.actions.DELIVER_ABORT({ w: m.to === 'worker0' ? 0 : 1 });
      }
      const s = spec.getState();
      assert.deepEqual(await project(h), { ...s, msgs: [...s.msgs] }, `walk ${walk} step ${step}`);
    }
  }
});

