cancel(): Outcome {
  if (this.status !== 'running') return refuse(`the run is ${this.status}, not running`);
  this.status = 'cancelling';
  this.tasks.forEach((t, i) => {
    if (t === 'assigned') this.send(RUN_ID, WORKERS[i], 'Abort', {});
  });
