'use strict';

// SAM v2 strict spec of src/host.impl.ts: the run, its two workers, and the
// network between them. `msgs` is the in-flight multiset, kept sorted, each
// message encoded as 'Assign:<task>', 'Abort:<task>' or 'Report:<task>:<outcome>'.
// Delivery of any in-flight message is an environment action, so the checker
// explores every arrival order.

const { createInstance } = require('@cognitive-fab/sam-pattern');

const instance = createInstance({ strict: true, hasAsyncActions: false });

const INITIAL_STATE = { run: 'idle', task0: 'idle', task1: 'idle', w0: 'idle', w1: 'idle', r0: false, r1: false, msgs: [] };

const W = [{ w: 0 }, { w: 1 }];
const OUTCOMES = ['completed', 'failed', 'cancelled'];
const taskKey = (i) => (i === 0 ? 'task0' : 'task1');
const workerKey = (i) => (i === 0 ? 'w0' : 'w1');
const add = (msgs, ...more) => [...msgs, ...more].sort();
const remove = (msgs, m) => {
  const i = msgs.indexOf(m);
  return [...msgs.slice(0, i), ...msgs.slice(i + 1)];
};

// The worker finishes: idle, and a report on the wire.
const finish = (outcome) => (model) => (proposal, { reject, next, unchanged }) => {
  const k = workerKey(proposal.w);
  if (model[k] !== 'busy') return reject('worker-not-busy');
  next[k] = 'idle';
  next.msgs = add(model.msgs, `Report:${proposal.w}:${outcome}`);
  unchanged('run', 'task0', 'task1', 'r0', 'r1', proposal.w === 0 ? 'w1' : 'w0');
};

const control = instance({
  initialState: { ...INITIAL_STATE, msgs: [] },
  component: {
    modelShape: {
      run: { type: 'string' },
      task0: { type: 'string' },
      task1: { type: 'string' },
      w0: { type: 'string' },
      w1: { type: 'string' },
      r0: { type: 'boolean' },
      r1: { type: 'boolean' },
      msgs: { type: 'array' },
    },
    actions: {
      START: { action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] },
      CANCEL: { action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] },
      WORK_DONE: { action: (data = {}) => ({ ...data }), schema: { w: 'number' }, domain: W },
      WORK_FAILED: { action: (data = {}) => ({ ...data }), schema: { w: 'number' }, domain: W },
      DELIVER_ASSIGN: { action: (data = {}) => ({ ...data }), schema: { w: 'number' }, domain: W },
      DELIVER_ABORT: { action: (data = {}) => ({ ...data }), schema: { w: 'number' }, domain: W },
      DELIVER_REPORT: {
        action: (data = {}) => ({ ...data }),
        schema: { w: 'number', outcome: 'string' },
        domain: [0, 1].flatMap((w) => OUTCOMES.map((outcome) => ({ w, outcome }))),
      },
    },
    acceptors: {
      START: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.run !== 'idle') return reject('already-started');
        next.run = 'running';
        next.task0 = 'assigned';
        next.task1 = 'assigned';
        unchanged('r0', 'r1');
        next.msgs = add(model.msgs, 'Assign:0', 'Assign:1');
        unchanged('w0', 'w1');
