      CANCEL: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.run !== 'running') return reject('not-running');
        next.run = 'cancelling';
        const aborts = [0, 1].filter((i) => model[taskKey(i)] === 'assigned').map((i) => `Abort:${i}`);
        next.msgs = add(model.msgs, ...aborts);
        unchanged('task0', 'task1', 'w0', 'w1', 'r0', 'r1');
