      WORK_FAILED: finish('failed'),
      DELIVER_ASSIGN: (model) => (proposal, { reject, next, unchanged }) => {
        const m = `Assign:${proposal.w}`;
        if (!model.msgs.includes(m)) return reject('not-in-flight');
