  const spec = loadSpec(new URL('../spec/run-workers.cjs', import.meta.url).pathname.replace(/^\/(\w:)/, '$1'));
  let seed = 12345;
  const rand = (n: number) => {
    seed = (seed * 1103515245 + 12345) % 2 ** 31;
    return seed % n;
  };
  const project = async (h: Host) => {
    const r = await h.run();
    const msgs = (await h.inFlight()).map((m) => {
      if (m.action === 'Report') return `Report:${m.data.task}:${m.data.outcome}`;
      return `${m.action}:${m.to === 'worker0' ? 0 : 1}`;
    }).sort();
    return {
      run: r.status, task0: r.task0, task1: r.task1, r0: r.retried0, r1: r.retried1,
      w0: (await h.worker('worker0'))!.status, w1: (await h.worker('worker1'))!.status, msgs,
    };
  };
  for (let walk = 0; walk < 300; walk++) {
    const h = await createHost();
    spec.init();
    for (let step = 0; step < 14; step++) {
      const msgs = await h.inFlight();
      const choice = rand(5 + msgs.length);
      const w = rand(2);
      const wid = `worker${w}`;
      if (choice === 0) { await h.start(); spec.actions.START({}); }
      else if (choice === 1) { await h.cancel(); spec.actions.CANCEL({}); }
      else if (choice === 2) { await h.workDone(wid); spec.actions.WORK_DONE({ w }); }
      else if (choice === 3) { await h.workFailed(wid); spec.actions.WORK_FAILED({ w }); }
      else if (choice === 4) { await h.workDone('bogus'); }
      else {
        const m = msgs[choice - 5];
        await h.deliver(m.id);
        if (m.action === 'Report') spec.actions.DELIVER_REPORT({ w: m.data.task, outcome: m.data.outcome });
        else if (m.action === 'Assign') spec.actions.DELIVER_ASSIGN({ w: m.to === 'worker0' ? 0 : 1 });
        else spec.actions.DELIVER_ABORT({ w: m.to === 'worker0' ? 0 : 1 });
      }
      const s = spec.getState();
      assert.deepEqual(await project(h), { ...s, msgs: [...s.msgs] }, `walk ${walk} step ${step}`);
    }
  }

