    if (this.status !== 'busy') return refuse(`${this.id} is not busy`);
    this.report(outcome);
    return ok();
  }

  receive(action: string): void {
    if (action === 'Assign' && this.status === 'idle') this.status = 'busy';
    else if (action === 'Abort' && this.status === 'busy') this.report('cancelled');
  }

  private report(outcome: Report): void {
    this.status = 'idle';
    this.send(this.id, RUN_ID, 'Report', { task: this.task, outcome });
  }
}

