9	const { createInstance } = require('@cognitive-fab/sam-pattern');
10	
11	const instance = createInstance({ strict: true, hasAsyncActions: false });
12	
13	const INITIAL_STATE = { run: 'idle', task0: 'idle', task1: 'idle', w0: 'idle', w1: 'idle', r0: false, r1: false, msgs: [] };
14	
15	const W = [{ w: 0 }, { w: 1 }];
16	const OUTCOMES = ['completed', 'failed', 'cancelled'];
17	const taskKey = (i) => (i === 0 ? 'task0' : 'task1');
18	const workerKey = (i) => (i === 0 ? 'w0' : 'w1');
19	const add = (msgs, ...more) => [...msgs, ...more].sort();
20	const remove = (msgs, m) => {
21	  const i = msgs.indexOf(m);
22	  return [...msgs.slice(0, i), ...msgs.slice(i + 1)];
23	};
24	
25	// The run's status once task statuses a and b are recorded.
26	const statusAfter = (current, a, b) => {
27	  const both = a !== 'assigned' && b !== 'assigned';
28	  if (a === 'completed' && b === 'completed') return 'completed';
29	  if (both && (a === 'failed' || b === 'failed')) return 'failed';
30	  if (both) return 'cancelled';
31	  return current;
32	};
33	
34	// The worker finishes: idle, and a report on the wire.
35	const finish = (outcome) => (model) => (proposal, { reject, next, unchanged }) => {
36	  const k = workerKey(proposal.w);
