import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';
import type { Host, Message } from '../host.ts';
// @ts-ignore -- plain JS module from the polygraph tool
import { loadSpec } from '../tools/polygraph/scripts/load-spec.mjs';

const deliverWhere = async (h: Host, pred: (m: Message) => boolean) => {
  const m = (await h.inFlight()).find(pred);
  assert.ok(m, 'expected message in flight');
  await h.deliver(m.id);
};

const R = (status: string, task0: string, task1: string, processed = 0, retried0 = false, retried1 = false) =>
  ({ status, task0, task1, retried0, retried1, processed });

test('fresh system is idle', async () => {
  const h = await createHost();
  assert.deepEqual(await h.run(), R('idle', 'idle', 'idle'));
  assert.deepEqual(await h.worker('worker0'), { status: 'idle' });
  assert.equal(await h.worker('nobody'), null);
  assert.deepEqual(await h.inFlight(), []);
  assert.equal((await h.cancel()).ok, false);
  assert.equal((await h.workDone('worker0', 1)).ok, false);
  assert.equal((await h.workDone('x', 1)).ok, false);
});

test('happy path completes and totals items', async () => {
  const h = await createHost();
  assert.deepEqual(await h.start(), { ok: true });
  assert.equal((await h.start()).ok, false);
  const msgs = await h.inFlight();
  assert.equal(msgs.length, 2);
  assert.deepEqual(msgs.map((m) => [m.from, m.to, m.action, m.data]).sort(), [
    ['run', 'worker0', 'Assign', {}],
    ['run', 'worker1', 'Assign', {}],
  ]);
  await h.deliverAll();
  assert.deepEqual(await h.worker('worker1'), { status: 'busy' });
  assert.deepEqual(await h.workDone('worker0', 2), { ok: true });
  const [r] = await h.inFlight();
  assert.deepEqual([r.from, r.to, r.action, r.data], ['worker0', 'run', 'Report', { task: 0, outcome: 'completed', items: 2 }]);
  await h.deliverAll();
  assert.deepEqual(await h.run(), R('running', 'completed', 'assigned', 2));
  await h.workDone('worker1', 1);
  await h.deliverAll();
  assert.deepEqual(await h.run(), R('completed', 'completed', 'completed', 3));
});

test('workDone refuses items other than 1 or 2, changing nothing', async () => {
  const h = await createHost();
  await h.start();
  await h.deliverAll();
  for (const items of [0, 3, -1, 1.5, NaN]) {
    assert.equal((await h.workDone('worker0', items)).ok, false);
  }
  assert.deepEqual(await h.worker('worker0'), { status: 'busy' });
  assert.deepEqual(await h.inFlight(), []);
});

test('failed and cancelled reports carry 0 items', async () => {
  const h = await createHost();
  await h.start();
  await h.deliverAll();
  await h.workFailed('worker0');
  await h.cancel();
  const data = (await h.inFlight()).filter((m) => m.action === 'Report').map((m) => m.data);
  assert.deepEqual(data, [{ task: 0, outcome: 'failed', items: 0 }]);
  await deliverWhere(h, (m) => m.action === 'Abort' && m.to === 'worker1');
  const cancelled = (await h.inFlight()).filter((m) => m.data.outcome === 'cancelled').map((m) => m.data);
  assert.deepEqual(cancelled, [{ task: 1, outcome: 'cancelled', items: 0 }]);
});

test('a first failure is retried, a second is recorded', async () => {
  const h = await createHost();
  await h.start();
  await h.deliverAll();
  await h.workFailed('worker1');
  await deliverWhere(h, (m) => m.action === 'Report');
  assert.deepEqual(await h.run(), R('running', 'assigned', 'assigned', 0, false, true));
  const msgs = await h.inFlight();
  assert.deepEqual(msgs.map((m) => [m.from, m.to, m.action, m.data]), [['run', 'worker1', 'Assign', {}]]);
  await h.deliverAll();
  assert.deepEqual(await h.worker('worker1'), { status: 'busy' });
  await h.workFailed('worker1');
  await h.deliverAll();
  assert.deepEqual(await h.run(), R('running', 'assigned', 'failed', 0, false, true));
  await h.workDone('worker0', 1);
  await h.deliverAll();
  assert.deepEqual(await h.run(), R('failed', 'completed', 'failed', 1, false, true));
});

test('a retried task can complete', async () => {
  const h = await createHost();
  await h.start();
  await h.deliverAll();
  await h.workFailed('worker0');
  await h.deliverAll();
  await h.workDone('worker0', 2);
  await h.workDone('worker1', 2);
  await h.deliverAll();
  assert.deepEqual(await h.run(), R('completed', 'completed', 'completed', 4, true, false));
});

test('a failure while cancelling is recorded, not retried', async () => {
  const h = await createHost();
  await h.start();
  await h.deliverAll();
  await h.workFailed('worker0');
  await h.cancel();
  await deliverWhere(h, (m) => m.action === 'Report');
  assert.deepEqual(await h.run(), R('cancelling', 'failed', 'assigned'));
  await h.deliverAll();
  assert.deepEqual(await h.run(), R('failed', 'failed', 'cancelled'));
});

test('cancel aborts only assigned tasks', async () => {
  const h = await createHost();
  await h.start();
  await h.deliverAll();
  await h.workDone('worker0', 1);
  await h.deliverAll();
  assert.deepEqual(await h.cancel(), { ok: true });
  assert.equal((await h.cancel()).ok, false);
  const msgs = await h.inFlight();
  assert.deepEqual(msgs.map((m) => [m.to, m.action]), [['worker1', 'Abort']]);
  await h.deliverAll();
  assert.deepEqual(await h.run(), R('cancelled', 'completed', 'cancelled', 1));
  assert.deepEqual(await h.worker('worker1'), { status: 'idle' });
});

