  await h.workDone('worker1', 2);
  await h.deliverAll();
  assert.deepEqual(await h.run(), R('failed', 'failed', 'completed', 2));
});

test('a report arriving after a timeout is ignored and adds nothing', async () => {
  const h = await createHost();
  await h.start();
  await h.deliverAll();
  await h.workDone('worker0', 2);
  await h.taskTimeout(0);
  await h.deliverAll();
