import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';
import type { Host, Message } from '../host.ts';
// @ts-ignore -- plain JS module from the polygraph tool
import { loadSpec } from '../tools/polygraph/scripts/load-spec.mjs';

const deliverWhere = async (h: Host, pred: (m: Message) => boolean) => {
  const m = (await h.inFlight()).find(pred);
  assert.ok(m, 'expected message in flight');
  await h.deliver(m.id);
};

test('fresh system is idle', async () => {
  const h = await createHost();
  assert.deepEqual(await h.run(), { status: 'idle', task0: 'idle', task1: 'idle', retried0: false, retried1: false });
  assert.deepEqual(await h.worker('worker0'), { status: 'idle' });
  assert.equal(await h.worker('nobody'), null);
  assert.deepEqual(await h.inFlight(), []);
  assert.equal((await h.cancel()).ok, false);
  assert.equal((await h.workDone('worker0')).ok, false);
  assert.equal((await h.workDone('x')).ok, false);
});

test('happy path completes', async () => {
  const h = await createHost();
  assert.deepEqual(await h.start(), { ok: true });
  assert.equal((await h.start()).ok, false);
  const msgs = await h.inFlight();
  assert.equal(msgs.length, 2);
  assert.deepEqual(msgs.map((m) => [m.from, m.to, m.action, m.data]).sort(), [
    ['run', 'worker0', 'Assign', {}],
    ['run', 'worker1', 'Assign', {}],
  ]);
  await h.deliverAll();
  assert.deepEqual(await h.worker('worker1'), { status: 'busy' });
  assert.deepEqual(await h.workDone('worker0'), { ok: true });
  const [r] = await h.inFlight();
  assert.deepEqual([r.from, r.to, r.action, r.data], ['worker0', 'run', 'Report', { task: 0, outcome: 'completed' }]);
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'running', task0: 'completed', task1: 'assigned', retried0: false, retried1: false });
  await h.workDone('worker1');
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'completed', task0: 'completed', task1: 'completed', retried0: false, retried1: false });
});

test('a first failure is retried, a second is recorded', async () => {
  const h = await createHost();
  await h.start();
  await h.deliverAll();
  await h.workFailed('worker1');
  await deliverWhere(h, (m) => m.action === 'Report');
  assert.deepEqual(await h.run(), { status: 'running', task0: 'assigned', task1: 'assigned', retried0: false, retried1: true });
  const msgs = await h.inFlight();
  assert.deepEqual(msgs.map((m) => [m.from, m.to, m.action, m.data]), [['run', 'worker1', 'Assign', {}]]);
  await h.deliverAll();
  assert.deepEqual(await h.worker('worker1'), { status: 'busy' });
  await h.workFailed('worker1');
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'running', task0: 'assigned', task1: 'failed', retried0: false, retried1: true });
  await h.workDone('worker0');
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'failed', task0: 'completed', task1: 'failed', retried0: false, retried1: true });
});

test('a retried task can complete', async () => {
  const h = await createHost();
  await h.start();
  await h.deliverAll();
  await h.workFailed('worker0');
  await h.deliverAll();
  await h.workDone('worker0');
  await h.workDone('worker1');
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'completed', task0: 'completed', task1: 'completed', retried0: true, retried1: false });
});

test('a failure while cancelling is recorded, not retried', async () => {
  const h = await createHost();
  await h.start();
  await h.deliverAll();
  await h.workFailed('worker0');
  await h.cancel();
  await deliverWhere(h, (m) => m.action === 'Report');
  assert.deepEqual(await h.run(), { status: 'cancelling', task0: 'failed', task1: 'assigned', retried0: false, retried1: false });
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'failed', task0: 'failed', task1: 'cancelled', retried0: false, retried1: false });
});

test('cancel aborts only assigned tasks', async () => {
  const h = await createHost();
  await h.start();
  await h.deliverAll();
  await h.workDone('worker0');
  await h.deliverAll();
  assert.deepEqual(await h.cancel(), { ok: true });
  assert.equal((await h.cancel()).ok, false);
  const msgs = await h.inFlight();
  assert.deepEqual(msgs.map((m) => [m.to, m.action]), [['worker1', 'Abort']]);
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'cancelled', task0: 'completed', task1: 'cancelled', retried0: false, retried1: false });
  assert.deepEqual(await h.worker('worker1'), { status: 'idle' });
});

test('completion report racing an abort still completes', async () => {
  const h = await createHost();
  await h.start();
  await h.deliverAll();
  await h.workDone('worker0');
  await h.workDone('worker1');
  await h.cancel();
  assert.equal((await h.run()).status, 'cancelling');
  await deliverWhere(h, (m) => m.action === 'Abort');
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'completed', task0: 'completed', task1: 'completed', retried0: false, retried1: false });
});

const R = (status: string, task0: string, task1: string, retried0 = false, retried1 = false) =>
  ({ status, task0, task1, retried0, retried1 });

test('taskTimeout is refused unless the task is assigned in a live run', async () => {
  const h = await createHost();
  assert.equal((await h.taskTimeout(0)).ok, false);
  await h.start();
  assert.equal((await h.taskTimeout(2)).ok, false);
  assert.equal((await h.taskTimeout(-1)).ok, false);
  await h.deliverAll();
  await h.workDone('worker0');
  await h.deliverAll();
  assert.equal((await h.taskTimeout(0)).ok, false);
  assert.deepEqual(await h.taskTimeout(1), { ok: true });
  assert.deepEqual(await h.run(), R('failed', 'completed', 'failed'));
  assert.equal((await h.taskTimeout(1)).ok, false);
});

test('timeout fails the task without retry and aborts its worker', async () => {
  const h = await createHost();
  await h.start();
  await h.deliverAll();
  assert.deepEqual(await h.taskTimeout(0), { ok: true });
  assert.deepEqual(await h.run(), R('running', 'failed', 'assigned'));
  const msgs = await h.inFlight();
  assert.deepEqual(msgs.map((m) => [m.from, m.to, m.action, m.data]), [['run', 'worker0', 'Abort', {}]]);
  await h.deliverAll();
  assert.deepEqual(await h.worker('worker0'), { status: 'idle' });
  assert.deepEqual(await h.run(), R('running', 'failed', 'assigned'));
  await h.workDone('worker1');
  await h.deliverAll();
  assert.deepEqual(await h.run(), R('failed', 'failed', 'completed'));
});

test('a report arriving after a timeout is ignored', async () => {
  const h = await createHost();
  await h.start();
  await h.deliverAll();
  await h.workFailed('worker0');
  await h.taskTimeout(0);
  await h.deliverAll();
  assert.deepEqual(await h.run(), R('running', 'failed', 'assigned'));
  assert.deepEqual(await h.inFlight(), []);
});

test('timeout while cancelling settles the task as failed', async () => {
  const h = await createHost();
  await h.start();
  await h.deliverAll();
  await h.cancel();
  await h.taskTimeout(1);
  await h.deliverAll();
  assert.deepEqual(await h.run(), R('failed', 'cancelled', 'failed'));
});

